def count_neighbors(grid, r, c):
    """Count non-background neighbors"""
    count = 0
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == grid[r][c]:
                count += 1
    return count

output_coherent = []
for row in range(16):
    r_out = []
    for col in range(11):
        val = grid[row][col]
        if val != 9:  # Not background
            if count_neighbors(grid, row, col) > 0:  # Has same-value neighbor
                r_out.append(val)
            else:
                r_out.append(9)  # Isolated, becomes background
        else:
            r_out.append(9)
    output_coherent.append(r_out)

print("Keep only coherent (>0 same-value neighbor) non-background:")
for i, row in enumerate(output_coherent):
    print(' '.join(map(str, row)))

