# Find connected components more carefully using flood fill / BFS
from collections import deque

visited = set()
clusters = defaultdict(list)

for r in range(16):
    for c in range(11):
        if grid[r][c] != 9 and (r,c) not in visited:
            # Start BFS from this cell
            component = []
            queue = deque([(r,c)])
            while queue:
                cr, cc = queue.popleft()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                val = grid[cr][cc]
                component.append((cr, cc))
                # Check neighbors
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 16 and 0 <= nc < 11:
                        if grid[nr][nc] == val and (nr, nc) not in visited:
                            queue.append((nr, nc))
            clusters[(val, len(component))] = component

print(f"Number of distinct clusters: {len(clusters)}")
for key, comp in sorted(clusters.items()):
    print(f"{key}: size {len(comp)}")

